/*!
 * qrcode.min.js — generador de códigos QR autónomo (modo byte / UTF-8).
 * Basado en la implementación de dominio público de Kazuhiko Arase (MIT).
 * Sin dependencias ni red. Uso:
 *   const qr = qrcode(0, 'M');     // 0 = tipo automático, ECC: L/M/Q/H
 *   qr.addData('https://...');
 *   qr.make();
 *   qr.renderTo(elementoCanvasOSvg, { size: 220, margin: 4 });
 *   const n = qr.getModuleCount();  qr.isDark(row, col);
 */
var qrcode = (function () {
  // ── Galois field tables ──
  var EXP = [], LOG = [];
  (function () {
    for (var i = 0; i < 8; i++) EXP[i] = 1 << i;
    for (i = 8; i < 256; i++) EXP[i] = EXP[i-4] ^ EXP[i-5] ^ EXP[i-6] ^ EXP[i-8];
    for (i = 0; i < 255; i++) LOG[EXP[i]] = i;
  })();
  function gexp(n){ while(n<0)n+=255; while(n>=256)n-=255; return EXP[n]; }
  function glog(n){ if(n<1) throw new Error('glog('+n+')'); return LOG[n]; }

  function Poly(num, shift){
    var n = []; var off = 0;
    while(off < num.length && num[off] === 0) off++;
    for(var i=0;i<num.length-off;i++) n[i]=num[i+off];
    for(i=0;i<shift;i++) n.push(0);
    this.num = n;
  }
  Poly.prototype.get = function(i){ return this.num[i]; };
  Poly.prototype.len = function(){ return this.num.length; };
  Poly.prototype.mul = function(e){
    var n = new Array(this.len()+e.len()-1);
    for(var i=0;i<n.length;i++) n[i]=0;
    for(i=0;i<this.len();i++)
      for(var j=0;j<e.len();j++)
        n[i+j] ^= gexp(glog(this.get(i)) + glog(e.get(j)));
    return new Poly(n,0);
  };
  Poly.prototype.mod = function(e){
    if(this.len()-e.len()<0) return this;
    var ratio = glog(this.get(0)) - glog(e.get(0));
    var n = this.num.slice();
    for(var i=0;i<e.len();i++) n[i] ^= gexp(glog(e.get(i))+ratio);
    return new Poly(n,0).mod(e);
  };
  function rsPoly(ec){
    var p = new Poly([1],0);
    for(var i=0;i<ec;i++) p = p.mul(new Poly([1, gexp(i)],0));
    return p;
  }

  // ── RS block layout: [count, totalWords, dataWords] per (type,ecc) ──
  // ECC index L=0,M=1,Q=2,H=3. Tablas para tipos 1..10 (suficiente para URLs cortas).
  var RS = {
    1:[[1,26,19],[1,26,16],[1,26,13],[1,26,9]],
    2:[[1,44,34],[1,44,28],[1,44,22],[1,44,16]],
    3:[[1,70,55],[1,70,44],[2,35,17],[2,35,13]],
    4:[[1,100,80],[2,50,32],[2,50,24],[4,25,9]],
    5:[[1,134,108],[2,67,43],[2,33,15,2,34,16],[2,33,11,2,34,12]],
    6:[[2,86,68],[4,43,27],[4,43,19],[4,43,15]],
    7:[[2,98,78],[4,49,31],[2,32,14,4,33,15],[4,39,13,1,40,14]],
    8:[[2,121,97],[2,60,38,2,61,39],[4,40,18,2,41,19],[4,40,14,2,41,15]],
    9:[[2,146,116],[3,58,36,2,59,37],[4,36,16,4,37,17],[4,36,12,4,37,13]],
    10:[[2,86,68,2,87,69],[4,69,43,1,70,44],[6,43,19,2,44,20],[6,43,15,2,44,16]]
  };
  var ECC_BITS = {L:1,M:0,Q:3,H:2};

  function rsBlocks(type, ecKey){
    var raw = RS[type][ {L:0,M:1,Q:2,H:3}[ecKey] ];
    var list = [];
    for(var i=0;i<raw.length;i+=3){
      var cnt=raw[i], tot=raw[i+1], dat=raw[i+2];
      for(var j=0;j<cnt;j++) list.push({total:tot,data:dat});
    }
    return list;
  }

  // ── BitBuffer ──
  function Bits(){ this.buf=[]; this.len=0; }
  Bits.prototype.put = function(num, n){
    for(var i=0;i<n;i++) this.putBit(((num>>>(n-i-1))&1)===1);
  };
  Bits.prototype.putBit = function(bit){
    var i = Math.floor(this.len/8);
    if(this.buf.length<=i) this.buf.push(0);
    if(bit) this.buf[i] |= (0x80 >>> (this.len%8));
    this.len++;
  };

  function utf8(str){
    var out=[];
    for(var i=0;i<str.length;i++){
      var c=str.charCodeAt(i);
      if(c<0x80) out.push(c);
      else if(c<0x800){ out.push(0xc0|(c>>6),0x80|(c&0x3f)); }
      else if(c<0xd800||c>=0xe000){ out.push(0xe0|(c>>12),0x80|((c>>6)&0x3f),0x80|(c&0x3f)); }
      else { // surrogate pair
        i++; var c2=str.charCodeAt(i);
        c=0x10000+(((c&0x3ff)<<10)|(c2&0x3ff));
        out.push(0xf0|(c>>18),0x80|((c>>12)&0x3f),0x80|((c>>6)&0x3f),0x80|(c&0x3f));
      }
    }
    return out;
  }

  function QR(typeNumber, ecKey){
    this.type = typeNumber || 0;
    this.ec = ecKey || 'M';
    this.data = '';
    this.modules = null;
    this.count = 0;
  }
  QR.prototype.addData = function(s){ this.data = s; };
  QR.prototype.getModuleCount = function(){ return this.count; };
  QR.prototype.isDark = function(r,c){ return this.modules[r][c]===true; };

  QR.prototype.make = function(){
    var bytes = utf8(this.data);
    // Elegir el tipo (versión) más pequeño que quepa
    var type = this.type;
    if(type<1){
      for(type=1; type<=10; type++){
        var cap = rsBlocks(type,this.ec).reduce(function(a,b){return a+b.data;},0);
        var lenBits = (type<10)?8:16; // modo byte: 8 bits para v1-9
        var need = 4 + lenBits + bytes.length*8;
        if(need <= cap*8) break;
      }
      if(type>10) throw new Error('Datos demasiado largos para QR<=v10');
    }
    this.type = type;
    this.count = type*4+17;

    // Construir bitstream
    var bits = new Bits();
    bits.put(4,4);                          // modo byte
    bits.put(bytes.length, (type<10)?8:16); // longitud
    for(var i=0;i<bytes.length;i++) bits.put(bytes[i],8);

    var blocks = rsBlocks(type,this.ec);
    var totalData = blocks.reduce(function(a,b){return a+b.data;},0);
    if(bits.len+4 <= totalData*8) bits.put(0,4); // terminador
    while(bits.len%8!==0) bits.putBit(false);
    var pad=[0xEC,0x11], pi=0;
    while(bits.buf.length < totalData){ bits.buf.push(pad[pi%2]); pi++; }

    // Repartir en bloques + RS
    var dataBlocks=[], ecBlocks=[], off=0, maxData=0, maxEc=0;
    for(i=0;i<blocks.length;i++){
      var b=blocks[i]; var dc=b.data; var ecc=b.total-b.data;
      maxData=Math.max(maxData,dc); maxEc=Math.max(maxEc,ecc);
      var d=bits.buf.slice(off,off+dc); off+=dc;
      dataBlocks.push(d);
      var rsP=rsPoly(ecc);
      var raw=new Poly(d,rsP.len()-1);
      var mod=raw.mod(rsP);
      var ec=[];
      for(var j=0;j<rsP.len()-1;j++){ var idx=j+mod.len()-(rsP.len()-1); ec.push(idx>=0?mod.get(idx):0); }
      ecBlocks.push(ec);
    }
    var payload=[];
    for(i=0;i<maxData;i++) for(j=0;j<dataBlocks.length;j++) if(i<dataBlocks[j].length) payload.push(dataBlocks[j][i]);
    for(i=0;i<maxEc;i++) for(j=0;j<ecBlocks.length;j++) if(i<ecBlocks[j].length) payload.push(ecBlocks[j][i]);

    // Probar máscaras, quedarnos con la de menor penalización
    var best=null, bestPen=Infinity, bestMask=0;
    for(var mask=0;mask<8;mask++){
      var m=this._buildMatrix(payload, mask);
      var pen=this._penalty(m);
      if(pen<bestPen){ bestPen=pen; best=m; bestMask=mask; }
    }
    this.modules=best; this.mask=bestMask;
  };

  QR.prototype._buildMatrix = function(payload, mask){
    var n=this.count;
    var m=[]; for(var r=0;r<n;r++){ m[r]=[]; for(var c=0;c<n;c++) m[r][c]=null; }

    function placeFinder(m,r,c){
      for(var dr=-1;dr<=7;dr++) for(var dc=-1;dc<=7;dc++){
        var rr=r+dr, cc=c+dc;
        if(rr<0||rr>=m.length||cc<0||cc>=m.length) continue;
        var dark=(0<=dr&&dr<=6&&(dc===0||dc===6))||(0<=dc&&dc<=6&&(dr===0||dr===6))||(2<=dr&&dr<=4&&2<=dc&&dc<=4);
        m[rr][cc]=dark;
      }
    }
    placeFinder(m,0,0); placeFinder(m,0,n-7); placeFinder(m,n-7,0);

    // Timing
    for(var i=8;i<n-8;i++){ if(m[6][i]===null)m[6][i]=(i%2===0); if(m[i][6]===null)m[i][6]=(i%2===0); }

    // Alignment (solo tipos >=2; para v2..v10 hay un único patrón centrado)
    var alignPos = {2:[6,18],3:[6,22],4:[6,26],5:[6,30],6:[6,34],7:[6,22,38],8:[6,24,42],9:[6,26,46],10:[6,28,50]};
    var ap = alignPos[this.type];
    if(ap){
      for(var a=0;a<ap.length;a++) for(var b=0;b<ap.length;b++){
        var ar=ap[a], ac=ap[b];
        if(m[ar][ac]!==null) continue; // no pisar finders
        for(var y=-2;y<=2;y++) for(var x=-2;x<=2;x++){
          m[ar+y][ac+x]=(Math.max(Math.abs(x),Math.abs(y))!==1);
        }
      }
    }

    // Dark module
    m[n-8][8]=true;

    // Reservar zonas de formato
    function reserve(m,r,c){ if(m[r][c]===null) m[r][c]='res'; }
    for(i=0;i<9;i++){ reserve(m,8,i); reserve(m,i,8); }
    for(i=0;i<8;i++){ reserve(m,8,n-1-i); reserve(m,n-1-i,8); }

    // Colocar datos en zigzag
    var idx=0, dir=-1, row=n-1;
    for(var col=n-1; col>0; col-=2){
      if(col===6) col--;
      while(true){
        for(var ci=0;ci<2;ci++){
          var cc=col-ci;
          if(m[row][cc]===null){
            var dark=false;
            if(idx< payload.length*8){
              var byteVal=payload[Math.floor(idx/8)];
              dark=((byteVal>>>(7-(idx%8)))&1)===1;
            }
            // máscara
            var rr=row;
            var maskBit;
            switch(mask){
              case 0: maskBit=(rr+cc)%2===0; break;
              case 1: maskBit=rr%2===0; break;
              case 2: maskBit=cc%3===0; break;
              case 3: maskBit=(rr+cc)%3===0; break;
              case 4: maskBit=(Math.floor(rr/2)+Math.floor(cc/3))%2===0; break;
              case 5: maskBit=((rr*cc)%2)+((rr*cc)%3)===0; break;
              case 6: maskBit=(((rr*cc)%2)+((rr*cc)%3))%2===0; break;
              case 7: maskBit=(((rr+cc)%2)+((rr*cc)%3))%2===0; break;
            }
            if(maskBit) dark=!dark;
            m[row][cc]=dark;
            idx++;
          }
        }
        row+=dir;
        if(row<0||row>=n){ row-=dir; dir=-dir; break; }
      }
    }

    // Información de formato
    this._placeFormat(m, mask);

    // Limpiar 'res' restantes
    for(r=0;r<n;r++) for(c=0;c<n;c++) if(m[r][c]==='res') m[r][c]=false;
    return m;
  };

  QR.prototype._placeFormat = function(m, mask){
    var n=this.count;
    var data=(ECC_BITS[this.ec]<<3)|mask;
    var d=data<<10;
    var g=0x537;
    for(var i=0;i<5;i++){ if((d>>>(14-i))&1){ d^= (g<<(4-i)); } }
    var bits=((data<<10)|d) ^ 0x5412;
    for(i=0;i<15;i++){
      var bit=((bits>>>i)&1)===1;
      // alrededor del finder superior-izquierdo
      if(i<6) m[i][8]=bit;
      else if(i<8) m[i+1][8]=bit;
      else if(i===8) m[8][7]=bit;
      else m[8][14-i]=bit;
      // copia
      if(i<8) m[8][n-1-i]=bit;
      else m[n-15+i][8]=bit;
    }
    m[n-8][8]=true;
  };

  QR.prototype._penalty = function(m){
    var n=m.length, pen=0, r,c,i;
    // Regla 1: corridas >=5 en filas y columnas
    for(r=0;r<n;r++){ var run=1; for(c=1;c<n;c++){ if(m[r][c]===m[r][c-1]){run++; if(run===5)pen+=3; else if(run>5)pen++;} else run=1; } }
    for(c=0;c<n;c++){ run=1; for(r=1;r<n;r++){ if(m[r][c]===m[r-1][c]){run++; if(run===5)pen+=3; else if(run>5)pen++;} else run=1; } }
    // Regla 2: bloques 2x2
    for(r=0;r<n-1;r++) for(c=0;c<n-1;c++){ var v=m[r][c]; if(v===m[r][c+1]&&v===m[r+1][c]&&v===m[r+1][c+1]) pen+=3; }
    // Regla 3: patrón 1011101 con 0000 a un lado
    var pat=[true,false,true,true,true,false,true];
    function match(line,k){ for(var t=0;t<7;t++) if(line[k+t]!==pat[t]) return false; return true; }
    for(r=0;r<n;r++){ var row=m[r]; for(c=0;c<n-6;c++){ if(match(row,c)){ var pre=true,post=true; for(i=1;i<=4;i++){ if(c-i<0||row[c-i]!==false)pre=false; if(c+6+i>=n||row[c+6+i]!==false)post=false; } if(pre||post)pen+=40; } } }
    for(c=0;c<n;c++){ var col=[]; for(r=0;r<n;r++)col[r]=m[r][c]; for(r=0;r<n-6;r++){ if(match(col,r)){ var p2=true,q2=true; for(i=1;i<=4;i++){ if(r-i<0||col[r-i]!==false)p2=false; if(r+6+i>=n||col[r+6+i]!==false)q2=false; } if(p2||q2)pen+=40; } } }
    // Regla 4: balance de oscuros
    var dark=0; for(r=0;r<n;r++)for(c=0;c<n;c++)if(m[r][c])dark++;
    var ratio=dark*100/(n*n); var k5=Math.floor(Math.abs(ratio-50)/5); pen+=k5*10;
    return pen;
  };

  // ── Render a canvas (preferido) o SVG ──
  QR.prototype.renderTo = function(el, opts){
    opts=opts||{};
    var margin=(opts.margin==null?4:opts.margin);
    var n=this.count;
    var fg=opts.color||'#0b1f33', bg=opts.background||'#ffffff';
    if(el.getContext){ // canvas
      var sizePx=opts.size||220;
      var cell=Math.floor(sizePx/(n+margin*2));
      var dim=cell*(n+margin*2);
      el.width=dim; el.height=dim;
      var ctx=el.getContext('2d');
      ctx.fillStyle=bg; ctx.fillRect(0,0,dim,dim);
      ctx.fillStyle=fg;
      for(var r=0;r<n;r++)for(var c=0;c<n;c++) if(this.modules[r][c])
        ctx.fillRect((c+margin)*cell,(r+margin)*cell,cell,cell);
    } else { // svg
      var total=n+margin*2, rects='';
      for(r=0;r<n;r++)for(c=0;c<n;c++) if(this.modules[r][c])
        rects+='<rect x="'+(c+margin)+'" y="'+(r+margin)+'" width="1.02" height="1.02"/>';
      el.innerHTML='<svg viewBox="0 0 '+total+' '+total+'" width="'+(opts.size||220)+'" height="'+(opts.size||220)+'" shape-rendering="crispEdges" xmlns="http://www.w3.org/2000/svg">'
        +'<rect width="'+total+'" height="'+total+'" fill="'+bg+'"/>'
        +'<g fill="'+fg+'">'+rects+'</g></svg>';
    }
  };

  function factory(typeNumber, ecKey){ return new QR(typeNumber, ecKey); }
  return factory;
})();
if (typeof module !== 'undefined' && module.exports) module.exports = qrcode;
